import { Button, Checkbox, Group, Stack } from '@mantine/core';
import { FormErrors, isNotEmpty, matches, useForm, when } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { AddressFields } from './AddressFields';
import { Address, AddressValues } from './types';

interface CheckoutValues extends AddressValues {
  sameAsBilling: boolean;
}

const emptyAddress: Address = {
  street: '',
  city: '',
  zip: '',
};

const addressRules = {
  street: isNotEmpty('Street is required'),
  city: isNotEmpty('City is required'),
  zip: matches(/^\d{5}$/, 'ZIP code must be 5 digits'),
};

export function SameAsBilling() {
  const form = useForm<CheckoutValues>({
    // Watchers of nested shipping fields are notified when the whole shipping object is set
    cascadeUpdates: true,
    initialValues: {
      billing: emptyAddress,
      shipping: emptyAddress,
      sameAsBilling: false,
    },
    validate: {
      billing: addressRules,
      shipping: {
        street: when((values) => !values.sameAsBilling, addressRules.street),
        city: when((values) => !values.sameAsBilling, addressRules.city),
        zip: when((values) => !values.sameAsBilling, addressRules.zip),
      },
    },
    enhanceGetInputProps: ({ field, form }) =>
      field.startsWith('shipping.') && form.getValues().sameAsBilling ? { disabled: true } : {},
  });

  // enhanceGetInputProps reads sameAsBilling during render, subscribe to rerender on toggle
  const sameAsBilling = form.useWatchValue('sameAsBilling');

  form.watch('sameAsBilling', ({ value }) => {
    if (value) {
      form.setFieldValue('shipping', { ...form.getValues().billing });
    }
  });

  form.watch('billing', ({ value }) => {
    if (form.getValues().sameAsBilling) {
      form.setFieldValue('shipping', { ...value }, { forceUpdate: false });
    }
  });

  const handleSubmit = (values: CheckoutValues) => {
    const { shipping } = values;
    notifications.show({
      title: 'Addresses saved',
      message: `Orders will be shipped to ${shipping.street}, ${shipping.zip} ${shipping.city}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <AddressFields form={form} prefix="billing" legend="Billing address" />

        <Checkbox
          size="md"
          label="Shipping address is the same as billing"
          {...form.getInputProps('sameAsBilling', { type: 'checkbox' })}
        />

        <AddressFields
          form={form}
          prefix="shipping"
          legend="Shipping address"
          disabled={sameAsBilling}
        />

        <Group justify="flex-end">
          <Button size="md" variant="default" onClick={form.reset}>
            Reset
          </Button>

          <Button size="md" type="submit">
            Save addresses
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { Fieldset, SimpleGrid, Stack, TextInput } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';
import { AddressValues } from './types';

interface AddressFieldsProps {
  form: UseFormReturnType<AddressValues>;
  prefix: 'billing' | 'shipping';
  legend: string;
  disabled?: boolean;
}

export function AddressFields({ form, prefix, legend, disabled = false }: AddressFieldsProps) {
  return (
    <Fieldset legend={legend}>
      <Stack gap="sm">
        <TextInput
          size="md"
          label="Street"
          placeholder="12 Main St"
          withAsterisk={!disabled}
          {...form.getInputProps(`${prefix}.street`)}
        />

        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            size="md"
            label="City"
            placeholder="Springfield"
            withAsterisk={!disabled}
            {...form.getInputProps(`${prefix}.city`)}
          />

          <TextInput
            size="md"
            label="ZIP code"
            placeholder="12345"
            withAsterisk={!disabled}
            {...form.getInputProps(`${prefix}.zip`)}
          />
        </SimpleGrid>
      </Stack>
    </Fieldset>
  );
}

export interface Address {
  street: string;
  city: string;
  zip: string;
}

export interface AddressValues {
  billing: Address;
  shipping: Address;
}
